func TestEveryFieldHasItsRowsShape(t *testing.T) {
	for _, s := range shapes {
		f, ok := reflect.TypeOf(s.v).FieldByName(s.field)
		if !ok {
			t.Errorf("%T has no field %s", s.v, s.field)
			continue
		}
		if got := f.Type.String(); got != s.typ {
			t.Errorf("%T.%s is %s, want %s", s.v, s.field, got, s.typ)
		}
	}
}
